 '{"key":"diver_medical","consent":{"required":true,"version":"dm-v1","text":{"en":"[Paste Diver Medical questionnaire text from PDF.]","es":"[Pegar cuestionario médico del PDF.]"}},"sections":[{"id":"dm","title":{"en":"Medical questionnaire","es":"Cuestionario médico"},"fields":[{"key":"over_45","type":"yes_no","required":true,"label":{"en":"I am 45 years of age or older","es":"Tengo 45 años o más"}},{"key":"over_45_confirmed","type":"checkbox","show_if":{"field":"over_45","op":"eq","value":"yes"},"required":true,"label":{"en":"I confirm I am 45+","es":"Confirmo que tengo 45+"}},{"key":"dm_q1","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Q1","es":"P1"}},{"key":"dm_box_A","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A","es":"Casilla A"}},{"key":"dm_q2","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Q2","es":"P2"}},{"key":"dm_box_B","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q2","op":"eq","value":"yes"},"label":{"en":"Box B","es":"Casilla B"}},{"key":"dm_q3","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Q3 (physician if YES)","es":"P3 (médico si SÍ)"}},{"key":"dm_q4","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Q4","es":"P4"}},{"key":"dm_box_C","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q4","op":"eq","value":"yes"},"label":{"en":"Box C","es":"Casilla C"}},{"key":"dm_q5","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Q5 (physician if YES)","es":"P5 (médico si SÍ)"}},{"key":"dm_q6","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Q6","es":"P6"}},{"key":"dm_box_D","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q6","op":"eq","value":"yes"},"label":{"en":"Box D","es":"Casilla D"}},{"key":"dm_q7","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Q7","es":"P7"}},{"key":"dm_box_E","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q7","op":"eq","value":"yes"},"